-- Guest Hub H7 — voice notes and images (15 Nov 2026, Ahmed — DECISIONS.md 2026-11-15 «Guest Hub H7: voice and images»).
-- Generated by scripts/hub-media-migration.mjs from scripts/hub-media-migration.src.sql and the latest definitions of the
-- functions it replaces — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   1. Two switches per unit, «الفويس» (voice_on) and «الصور» (images_on) — both OFF; only the system admin switches one on
--      (any assistant: edit holder of the branch may switch it off); a hidden unit can never have one on.
--   2. hub_messages: the transcript (guest text — the 12-month retention of the message text), its length and language, the
--      image's category (never anything read from the image), the media outcome (a fault is counted in the daily report).
--   3. The daily cap on transcribed minutes per unit (Settings hub_voice_daily_minutes, 60, «الميزانية», the system
--      admin's): past it, voice notes go to the team for the rest of the Riyadh day, and one alert email (hub_alerts
--      voice_cap) reaches the active admins.
--   4. The costs: OpenAI's transcription in hub_usage_daily as its own layer «transcribe» (per minute, audio_seconds —
--      outside the Claude budget, which is Anthropic's credit: hub_budget_state leaves it out); the image's vision call as
--      the layer «vision» (Claude tokens, inside the budget). Settings hub_models gains transcribe (gpt-transcribe) and
--      vision (claude-haiku-5-5); hub_model_prices gains gpt-transcribe (USD 0.0045 a minute, read 15 Nov 2026).
--   5. The H7 conversations of the conversation bank as test-lab items (tags conversation + media + h7).
-- No unit mode, licence or global switch changes; both new switches ship OFF. No phone number in this file.

-- ───────────────────────────────────────────── 1. columns and constraints ─────────────────────────────────────────────
alter table public.hub_units add column voice_on boolean not null default false;
alter table public.hub_units add column images_on boolean not null default false;
alter table public.hub_units add constraint hub_units_media_hidden check (status = 'active' or not (voice_on or images_on));
comment on column public.hub_units.voice_on is '«الفويس» (H7): voice notes transcribed (OpenAI gpt-transcribe) and answered as text. Off until the system admin switches it on.';
comment on column public.hub_units.images_on is '«الصور» (H7): images classified first (Claude vision) — identity / payment → the team, nothing read; screenshots read; problem photos → the team, high priority. Off until the system admin switches it on.';

alter table public.hub_messages add column transcript text check (transcript is null or char_length(transcript) <= 8000);
alter table public.hub_messages add column transcript_seconds numeric(8, 2) check (transcript_seconds is null or transcript_seconds >= 0);
alter table public.hub_messages add column transcript_language text check (transcript_language is null or transcript_language ~ '^[a-z]{2,8}$');
alter table public.hub_messages add column media_category text check (media_category is null or media_category in ('id_document', 'payment', 'screenshot', 'problem', 'place', 'other'));
alter table public.hub_messages add column media_status text check (media_status is null or media_status in
  ('transcribed', 'classified', 'too_long', 'voice_capped', 'failed_download', 'failed_transcribe', 'empty', 'unknown_language', 'failed_vision'));
comment on column public.hub_messages.transcript is 'H7: a voice note''s transcript — guest text, readable through the unit only (internal.can_unit), cleared with the message text after hub_retention_months.';
comment on column public.hub_messages.media_category is 'H7: an image''s category only — nothing read from an image is ever stored.';

alter table public.hub_usage_daily drop constraint hub_usage_daily_layer_check;
alter table public.hub_usage_daily add constraint hub_usage_daily_layer_check
  check (layer in ('understand', 'tag', 'compose', 'translate', 'suggest', 'draft_card', 'summary', 'staff_chat', 'vision', 'transcribe'));
alter table public.hub_usage_daily add column audio_seconds numeric(12, 2) not null default 0 check (audio_seconds >= 0);
comment on column public.hub_usage_daily.audio_seconds is 'H7: seconds of voice transcribed (the layer transcribe — OpenAI, per minute; outside the Claude budget).';

alter table public.hub_alerts drop constraint hub_alerts_kind_check;
alter table public.hub_alerts add constraint hub_alerts_kind_check
  check (kind in ('budget_pct', 'budget_cap', 'portfolio_pct', 'quality_drop', 'offer_ending', 'card_expiring', 'spike', 'escalation', 'complaint',
                  'webhook_silent', 'template_rejected', 'api_credit', 'flagged_wrong', 'model_error', 'voice_cap'));

-- ───────────────────────────────────────────── 2. the functions replaced ─────────────────────────────────────────────
-- internal.hub_setting_keys (20261113100000, copied): + hub_voice_daily_minutes (H7)

create or replace function internal.hub_setting_keys() returns text[]
language sql immutable set search_path = '' as $$
  select array['hub_assistant_on', 'hub_inbox_on', 'hub_models', 'hub_model_prices', 'hub_budget_daily_usd', 'hub_budget_monthly_usd',
               'hub_budget_alert_pct', 'hub_confidence_floor', 'hub_burst_ms', 'hub_quote_ttl_min', 'hub_confirm_ttl_min', 'hub_idle_close_hours',
               'hub_human_close_hours', 'hub_cancel_word_wait_hours', 'hub_reply_amber_min', 'hub_reply_red_min', 'hub_escalate_min',
               'hub_failed_understanding_max', 'hub_cards_per_turn', 'hub_reply_max_chars', 'hub_group_min_rooms', 'hub_rate_phone_hour',
               'hub_rate_replies_hour', 'hub_portfolio_limit', 'hub_portfolio_reserve', 'hub_wave_size', 'hub_wave_pause_min',
               'hub_offer_expiry_alert_days', 'hub_card_expiry_alert_days', 'hub_retention_months', 'hub_media_retention_days',
               'hub_spike_factor', 'hub_spike_min', 'hub_summary_time', 'hub_summary_money', 'hub_voice_daily_minutes']
$$;

-- internal.hub_setting_int_range (20261113100000, copied): the voice minutes (H7)

create or replace function internal.hub_setting_int_range(p_key text) returns integer[]
language sql immutable set search_path = '' as $$
  select case p_key
    when 'hub_budget_alert_pct' then array[1, 100]
    when 'hub_burst_ms' then array[0, 60000]
    when 'hub_quote_ttl_min' then array[1, 1440]
    when 'hub_confirm_ttl_min' then array[1, 1440]
    when 'hub_idle_close_hours' then array[1, 720]
    when 'hub_human_close_hours' then array[1, 720]
    -- inside the 24-hour window, so the opt-out reply can still be sent (spec §2.3.4)
    when 'hub_cancel_word_wait_hours' then array[1, 23]
    when 'hub_reply_amber_min' then array[1, 1440]
    when 'hub_reply_red_min' then array[1, 1440]
    when 'hub_escalate_min' then array[1, 1440]
    when 'hub_failed_understanding_max' then array[1, 10]
    when 'hub_cards_per_turn' then array[1, 20]
    when 'hub_reply_max_chars' then array[100, 4096]
    when 'hub_group_min_rooms' then array[2, 50]
    when 'hub_rate_phone_hour' then array[1, 1000]
    when 'hub_rate_replies_hour' then array[1, 1000]
    when 'hub_portfolio_limit' then array[1, 1000000]
    when 'hub_portfolio_reserve' then array[0, 1000000]
    when 'hub_wave_size' then array[1, 100000]
    when 'hub_wave_pause_min' then array[0, 1440]
    when 'hub_offer_expiry_alert_days' then array[0, 90]
    when 'hub_card_expiry_alert_days' then array[0, 90]
    when 'hub_retention_months' then array[1, 60]
    when 'hub_media_retention_days' then array[1, 3650]
    when 'hub_spike_min' then array[1, 1000]
    -- H7: transcribed minutes per unit per Riyadh day (60 — «الميزانية», the system admin's)
    when 'hub_voice_daily_minutes' then array[1, 1440]
  end
$$;

-- internal.hub_setting_check (20261113100000, copied): the transcription model and its per-minute price (H7)

create or replace function internal.hub_setting_check(p_key text, v jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  r integer[] := internal.hub_setting_int_range(p_key);
  n numeric;
  g jsonb;
  e record;
begin
  if r is not null then
    if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric <> floor((v #>> '{}')::numeric)
       or (v #>> '{}')::numeric not between r[1] and r[2] then
      raise exception 'settings.%: a whole number %–%', p_key, r[1], r[2] using errcode = '22023';
    end if;
    return;
  end if;
  case p_key
    when 'hub_assistant_on', 'hub_inbox_on', 'hub_summary_money' then
      if coalesce(jsonb_typeof(v), '') <> 'boolean' then raise exception 'settings.%: true or false', p_key using errcode = '22023'; end if;
      if v = 'true'::jsonb then
        g := internal.hub_switch_gates(p_key);
        if jsonb_array_length(g) > 0 then raise exception 'hub_not_ready' using errcode = 'P0001', detail = g::text; end if;
      end if;
    when 'hub_models' then
      -- H7: transcribe is OpenAI's model id (gpt-…); every other layer is Claude's
      if coalesce(jsonb_typeof(v), '') <> 'object' or not (v ?& array['understand', 'tag', 'translate', 'compose'])
         or exists (select 1 from jsonb_each(v) x where jsonb_typeof(x.value) <> 'string'
                      or x.value #>> '{}' !~ case when x.key = 'transcribe' then '^gpt-[a-z0-9.-]{3,60}$' else '^claude-[a-z0-9.-]{3,60}$' end) then
        raise exception 'settings.hub_models: understand, tag, translate, compose = claude model ids (transcribe: an OpenAI id)' using errcode = '22023';
      end if;
    when 'hub_model_prices' then
      -- [يُؤكَّد] from Anthropic's price page when the engine is built: null until then, else {model: {input, output}} USD / million tokens
      if jsonb_typeof(v) = 'null' then return; end if;
      if coalesce(jsonb_typeof(v), '') <> 'object' then raise exception 'settings.hub_model_prices: null or {model: {input, output}}' using errcode = '22023'; end if;
      for e in select * from jsonb_each(v) loop
        -- H7: OpenAI's transcription model is priced per minute: {per_minute} (USD)
        if e.key ~ '^gpt-[a-z0-9.-]{3,60}$' then
          if coalesce(jsonb_typeof(e.value -> 'per_minute'), '') <> 'number' or (e.value ->> 'per_minute')::numeric not between 0 and 100 then
            raise exception 'settings.hub_model_prices: null or {model: {input, output}} (an OpenAI model: {per_minute})' using errcode = '22023';
          end if;
          continue;
        end if;
        if e.key !~ '^claude-[a-z0-9.-]{3,60}$' or coalesce(jsonb_typeof(e.value -> 'input'), '') <> 'number' or coalesce(jsonb_typeof(e.value -> 'output'), '') <> 'number'
           or (e.value ->> 'input')::numeric not between 0 and 1000 or (e.value ->> 'output')::numeric not between 0 and 1000 then
          raise exception 'settings.hub_model_prices: null or {model: {input, output}}' using errcode = '22023';
        end if;
      end loop;
    when 'hub_budget_daily_usd', 'hub_budget_monthly_usd' then
      -- [يُؤكَّد] Ahmed sets the first trial week's cap before that week: null until then
      if jsonb_typeof(v) = 'null' then return; end if;
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric < 0 or (v #>> '{}')::numeric > 100000 then
        raise exception 'settings.%: null or a number 0–100000 (USD)', p_key using errcode = '22023';
      end if;
    when 'hub_confidence_floor' then
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric not between 0 and 1 then
        raise exception 'settings.hub_confidence_floor: a number 0–1' using errcode = '22023';
      end if;
    when 'hub_spike_factor' then
      if coalesce(jsonb_typeof(v), '') <> 'number' or (v #>> '{}')::numeric not between 1 and 100 then
        raise exception 'settings.hub_spike_factor: a number 1–100' using errcode = '22023';
      end if;
    when 'hub_summary_time' then
      if coalesce(v #>> '{}', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or jsonb_typeof(v) <> 'string' then
        raise exception 'settings.hub_summary_time: HH:MM' using errcode = '22023';
      end if;
    else
      raise exception 'unknown setting %', p_key using errcode = '22023';
  end case;
end;
$$;

-- public.hub_setting_set (20261114200000, copied): the voice minutes are the system admin's, like the budgets (H7)

create or replace function public.hub_setting_set(p_key text, p_value jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_batch uuid;
begin
  if not internal.can('assistant', 'edit') or not internal.all_branches() then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_key is null or not (p_key = any(internal.hub_setting_keys())) then raise exception 'unknown setting %', coalesce(p_key, '') using errcode = '22023'; end if;
  if p_key in ('hub_models', 'hub_model_prices') then raise exception 'hub_setting_read_only' using errcode = 'P0001'; end if;
  if p_key in ('hub_budget_daily_usd', 'hub_budget_monthly_usd', 'hub_budget_alert_pct', 'hub_voice_daily_minutes') and not internal.is_system_admin() then
    raise exception 'hub_system_admin_only' using errcode = 'P0001';
  end if;
  if p_key = 'hub_assistant_on' and p_value = 'true'::jsonb and not internal.is_system_admin() then
    raise exception 'hub_system_admin_only' using errcode = 'P0001';
  end if;
  if (select s.value from public.settings s where s.key = p_key) is not distinct from p_value then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.settings set value = p_value where key = p_key;
  if not found then raise exception 'unknown setting %', p_key using errcode = '22023'; end if;
  return jsonb_build_object('ok', true, 'batch_id', v_batch);
end;
$$;

-- internal.hub_budget_state (20261114920000, copied): the transcription left out of the Claude budget (H7)

create or replace function internal.hub_budget_state(p_now timestamptz default now()) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_today date := (p_now at time zone 'Asia/Riyadh')::date;
  v_month date := date_trunc('month', (p_now at time zone 'Asia/Riyadh')::date)::date;
  v_d jsonb := (select s.value from public.settings s where s.key = 'hub_budget_daily_usd');
  v_m jsonb := (select s.value from public.settings s where s.key = 'hub_budget_monthly_usd');
  v_pct integer := internal.hub_setting_int('hub_budget_alert_pct', 80);
  v_ds numeric;
  v_ms numeric;
  v_tds numeric;
  v_tms numeric;
  v_dl numeric;
  v_ml numeric;
  v_credit public.hub_alerts;
begin
  -- the live guests' budget counts live turns and the staff tools only — never the test lab or the simulator (Ahmed,
  -- 14 Nov 2026); the totals (every source) bound the lab, which may never push the live spend over the cap
  select coalesce(sum(u.cost_usd) filter (where u.day = v_today and u.source not in ('test_lab', 'simulator')), 0),
         coalesce(sum(u.cost_usd) filter (where u.source not in ('test_lab', 'simulator')), 0),
         coalesce(sum(u.cost_usd) filter (where u.day = v_today), 0), coalesce(sum(u.cost_usd), 0)
    into v_ds, v_ms, v_tds, v_tms from public.hub_usage_daily u where u.day >= v_month and u.day <= v_today
     -- H7: OpenAI's transcription is not Anthropic's credit: its own line in «الميزانية», never in the Claude budget
     and u.layer <> 'transcribe';
  v_dl := case when jsonb_typeof(v_d) = 'number' then (v_d #>> '{}')::numeric end;
  v_ml := case when jsonb_typeof(v_m) = 'number' then (v_m #>> '{}')::numeric end;
  select * into v_credit from public.hub_alerts a where a.kind = 'api_credit' and a.acknowledged_at is null and not a.is_test order by a.created_at desc limit 1;
  return jsonb_build_object(
    'day', v_today, 'month', to_char(v_month, 'YYYY-MM'), 'alert_pct', v_pct,
    'daily_budget', v_dl, 'monthly_budget', v_ml, 'daily_spent', round(v_ds, 6), 'monthly_spent', round(v_ms, 6),
    'total_daily_spent', round(v_tds, 6), 'total_monthly_spent', round(v_tms, 6), 'lab_daily_spent', round(v_tds - v_ds, 6),
    'lab_capped', (v_dl is not null and v_tds >= v_dl) or (v_ml is not null and v_tms >= v_ml),
    'unset', v_dl is null or v_ml is null,
    'daily_capped', v_dl is not null and v_ds >= v_dl, 'monthly_capped', v_ml is not null and v_ms >= v_ml,
    'capped', (v_dl is not null and v_ds >= v_dl) or (v_ml is not null and v_ms >= v_ml),
    'daily_alert', v_dl is not null and v_dl > 0 and v_ds >= v_dl * v_pct / 100.0,
    'monthly_alert', v_ml is not null and v_ml > 0 and v_ms >= v_ml * v_pct / 100.0,
    'api_credit', v_credit.id is not null,
    'api_credit_since', v_credit.created_at,
    'api_credit_last_try', (v_credit.payload ->> 'last_try_at')::timestamptz);
end;
$$;

-- public.hub_turn_claim (20261115200000, copied): the media switches, the stored file and transcript, the voice minutes; a voice note's transcript in the history (H7)

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    'replies_hour', (select count(*) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript)) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and r.is_test = c.is_test order by r.created_at desc limit 5) r),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'show_prices'), false)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

-- public.hub_turn_finish (20261115200000, copied): the vision layer, the transcriptions, the media outcomes, the voice-minutes alert (H7)

create or replace function public.hub_turn_finish(p_turn uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  m jsonb;
  v_cost numeric := 0;
  v_one numeric;
  v_to text := nullif(p ->> 'state', '');
  v_from text;
  v_test boolean;
  v_status text;
  v_out jsonb := '[]'::jsonb;
  v_id uuid;
  v_topics text[] := array(select jsonb_array_elements_text(coalesce(p -> 'topics', '[]'::jsonb)));
  v_draft jsonb := p -> 'draft';
  v_send boolean := false;
  v_seq integer := 0;
  v_unit uuid;
  v_ready boolean;
  x jsonb;
  v_capped boolean := false;
begin
  select * into t from public.hub_turns where id = p_turn for update;
  if t.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if t.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running', 'status', t.status); end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  v_test := t.mode = 'test';
  -- the models: every call counts in the budget (test runs included)
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if m ->> 'layer' in ('understand', 'tag', 'compose', 'summary', 'vision') and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_one := internal.hub_usage_add(t.unit_id, m ->> 'layer', 'turn', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, t.is_test);
      v_cost := v_cost + v_one;
    end if;
  end loop;
  -- H7: the transcriptions (OpenAI, per minute — never in the Claude budget) and what each voice note / image became: the
  -- transcript, its length and language, the image's category, the outcome — never anything read from an image
  for x in select * from jsonb_array_elements(coalesce(p -> 'audio', '[]'::jsonb)) loop
    if coalesce((x ->> 'seconds')::numeric, 0) > 0 and coalesce(x ->> 'model', '') ~ '^gpt-[a-z0-9.-]{3,60}$' then
      perform internal.hub_audio_add(t.unit_id, 'turn', x ->> 'model', (x ->> 'seconds')::numeric, t.is_test);
    end if;
  end loop;
  for x in select * from jsonb_array_elements(coalesce(p -> 'media', '[]'::jsonb)) loop
    if coalesce(x ->> 'id', '') ~ '^[0-9a-f-]{36}$' then
      update public.hub_messages
         set transcript = case when x ->> 'status' = 'transcribed' then left(nullif(btrim(x ->> 'transcript'), ''), 8000) else transcript end,
             transcript_seconds = coalesce(case when jsonb_typeof(x -> 'seconds') = 'number' then round((x ->> 'seconds')::numeric, 2) end, transcript_seconds),
             transcript_language = coalesce(case when coalesce(x ->> 'language', '') ~ '^[a-z]{2,8}$' then x ->> 'language' end, transcript_language),
             media_category = coalesce(case when x ->> 'category' in ('id_document', 'payment', 'screenshot', 'problem', 'place', 'other') then x ->> 'category' end, media_category),
             media_status = case when x ->> 'status' in ('transcribed', 'classified', 'too_long', 'voice_capped', 'failed_download', 'failed_transcribe', 'empty', 'unknown_language', 'failed_vision')
                                 then x ->> 'status' else media_status end
       where id = (x ->> 'id')::uuid and conversation_id = t.conversation_id and direction = 'in';
      if x ->> 'status' = 'voice_capped' then v_capped := true; end if;
    end if;
  end loop;
  -- the unit's daily minutes used up: ONE alert email to the active admins per unit and Riyadh day (hub-agent); an alert
  -- of an earlier day is closed first
  if v_capped and not t.is_test then
    update public.hub_alerts set acknowledged_at = now()
     where kind = 'voice_cap' and unit_id = t.unit_id and acknowledged_at is null and not is_test
       and coalesce(payload ->> 'day', '') <> ((now() at time zone 'Asia/Riyadh')::date)::text;
    insert into public.hub_alerts (kind, unit_id, payload)
    values ('voice_cap', t.unit_id, jsonb_build_object('day', ((now() at time zone 'Asia/Riyadh')::date)::text, 'minutes', internal.hub_setting_int('hub_voice_daily_minutes', 60)))
    on conflict do nothing;
  end if;
  update public.hub_turns
     set status = case when p ->> 'status' in ('done', 'failed', 'skipped') then p ->> 'status' else 'done' end,
         error = nullif(left(p ->> 'error', 40), ''), understanding = p -> 'understanding', decision = p -> 'decision',
         models = coalesce(p -> 'models', '[]'::jsonb), cost_usd = v_cost, guard_refusals = coalesce(p -> 'guard_refusals', '[]'::jsonb), finished_at = now()
   where id = t.id;
  -- topics and language: real data, whatever the mode
  update public.hub_conversations
     set topics = (select coalesce(array_agg(distinct x), '{}') from (select unnest(topics) x union select unnest(v_topics)) q where x ~ '^[a-z0-9_]{2,60}$'),
         language = coalesce(case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end, language),
         failed_understandings = case p ->> 'failed' when 'reset' then 0 when 'inc' then failed_understandings + 1 else failed_understandings end,
         out_of_scope = out_of_scope + case when coalesce((p ->> 'out_of_scope_inc')::boolean, false) then 1 else 0 end,
         tags = case when jsonb_typeof(p -> 'tags_add') = 'array'
                     then (select coalesce(array_agg(distinct x), '{}') from (select unnest(tags) x union select jsonb_array_elements_text(p -> 'tags_add')) q)
                     else tags end
   where id = c.id;
  if t.kind = 'tag' or p ->> 'status' in ('failed', 'skipped') and v_to is null then
    return jsonb_build_object('ok', true, 'messages', '[]'::jsonb, 'cost_usd', v_cost);
  end if;
  -- the draft (one open per conversation and run): a draft of another kind is superseded first
  if coalesce((p ->> 'draft_replace')::boolean, false) then
    update public.hub_drafts set status = 'superseded' where conversation_id = c.id and status = 'open' and sim = v_test;
  end if;
  if jsonb_typeof(v_draft) = 'object' then
    update public.hub_drafts set fields = coalesce(v_draft -> 'fields', fields), quote = coalesce(v_draft -> 'quote', quote), version = version + 1
     where conversation_id = c.id and status = 'open' and sim = v_test;
    if not found then
      insert into public.hub_drafts (conversation_id, kind, sim, fields, quote, is_test)
      values (c.id, coalesce(v_draft ->> 'kind', 'stay'), v_test, coalesce(v_draft -> 'fields', '{}'::jsonb), v_draft -> 'quote', c.is_test);
    end if;
  end if;
  if nullif(p ->> 'draft_close', '') is not null then
    update public.hub_drafts set status = p ->> 'draft_close' where conversation_id = c.id and status = 'open' and sim = v_test and p ->> 'draft_close' in ('abandoned', 'failed', 'superseded');
  end if;
  -- the next state: in «تجربة» the run's own state (test_state); otherwise the conversation's
  if v_test then
    v_from := coalesce(c.test_state, 'new');
    if v_to is not null and v_to <> v_from then
      update public.hub_conversations set test_state = v_to where id = c.id;
      insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
      values (c.id, 'test', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
    end if;
  else
    v_from := c.state;
    if v_to = 'human' and v_from = 'human' then
      if coalesce((p ->> 'resumed')::boolean, false) then
        -- resumed after a staff reply and handed again (H6c): a new hand-off, with its own staff alert
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', 'human', 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end, waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif p ->> 'resume_state' in ('inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then
        -- «بانتظار موظف»: where the assistant's flow stands while it waits (for the resume and «إعادة للمساعد»)
        update public.hub_conversations set state_before_human = p ->> 'resume_state' where id = c.id and state_before_human is distinct from p ->> 'resume_state';
      end if;
      if p ->> 'priority' = 'high' then
        update public.hub_conversations set priority = 'high' where id = c.id and priority <> 'high';
      end if;
    elsif v_to is not null and v_to <> v_from then
      if v_to = 'human' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', v_from, 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_before_human = case when v_from in ('new', 'inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then v_from else state_before_human end,
               state = 'human', state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end,
               waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif v_to = 'closed' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'close', v_from, 'closed', coalesce(nullif(p ->> 'reason', ''), 'assistant'), c.is_test);
        update public.hub_conversations set state = 'closed', state_changed_at = now(), closed_at = now(), waiting_since = null where id = c.id;
      else
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'state', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
        update public.hub_conversations set state = v_to, state_changed_at = now(), owner_kind = 'assistant', owner_staff_id = null where id = c.id;
      end if;
    elsif p ->> 'priority' = 'high' then
      update public.hub_conversations set priority = 'high' where id = c.id;
    end if;
  end if;
  -- the staff alert's line and the booking ref or room (H6c), on the conversation's waiting hand-off
  if not v_test and (nullif(p ->> 'handoff_summary', '') is not null or nullif(p ->> 'handoff_ref', '') is not null or coalesce((p ->> 'handoff_add')::boolean, false)) then
    update public.hub_handoffs h
       set summary = coalesce(h.summary, nullif(left(btrim(p ->> 'handoff_summary'), 120), '')),
           ref_text = coalesce(h.ref_text, nullif(left(btrim(p ->> 'handoff_ref'), 40), '')),
           additions = h.additions + case when coalesce((p ->> 'handoff_add')::boolean, false) then 1 else 0 end
      from public.hub_conversations x
     where x.id = c.id and h.id = x.handoff_id;
  end if;
  -- the hand-off note (code-composed, spec §2.6): an internal note at the top of the thread, never sent
  if nullif(btrim(coalesce(p ->> 'note', '')), '') is not null then
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, sent_at, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'system', 'note', left(btrim(p ->> 'note'), 2000), jsonb_build_object('handoff_note', true, 'test', v_test),
            'turn:' || t.id || ':note', case when v_test then 'test' else 'internal' end, now(), t.id, c.is_test)
    on conflict (idempotency_key) do nothing;
  end if;
  -- the messages: «تجربة» stored as test; «بموافقة الفريق» drafts wait for one tap, the notices go; live sends now
  select (ch.sending_enabled and internal.hub_setting_bool('hub_inbox_on') and g.hub_blocked_at is null and c.window_expires_at > now()) into v_ready
    from public.hub_channels ch, public.guest_profiles g where ch.id = c.channel_id and g.id = c.guest_profile_id;
  for m in select * from jsonb_array_elements(coalesce(p -> 'messages', '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    v_status := case when v_test then 'test'
                     -- «بموافقة الفريق»: every reply waits for one tap; «يرد تلقائيًا»: only a licensed topic goes by itself;
                     -- the hand-off notices go out in both (approved copy, spec §2.10)
                     when t.mode in ('shadow', 'live') and not coalesce((m ->> 'notice')::boolean, false)
                          and (t.mode = 'shadow' or not coalesce((m ->> 'licensed')::boolean, false)) then 'pending_approval'
                     when not coalesce(v_ready, false) then 'failed'
                     else 'queued' end;
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, language, idempotency_key, status, error_code, sent_at,
                                     source_card_ids, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'assistant', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end,
            left(m ->> 'body', 4096), coalesce(m -> 'payload', '{}'::jsonb) || jsonb_build_object('notice', coalesce((m ->> 'notice')::boolean, false), 'topics', to_jsonb(v_topics)),
            case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end,
            'turn:' || t.id || ':' || coalesce(m ->> 'seq', v_seq::text), v_status,
            case when v_status = 'failed' then 'not_ready' end, now() + make_interval(secs => v_seq * 0.001),
            coalesce(array(select x::uuid from jsonb_array_elements_text(coalesce(m -> 'source_card_ids', '[]'::jsonb)) x where x ~ '^[0-9a-f-]{36}$'), '{}'),
            t.id, c.is_test)
    on conflict (idempotency_key) do nothing
    returning id into v_id;
    if v_id is not null then
      if v_status = 'queued' then
        v_send := true;
        v_out := v_out || jsonb_build_object('id', v_id, 'kind', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end, 'body', left(m ->> 'body', 4096),
                                             'payload', coalesce(m -> 'payload', '{}'::jsonb), 'notice', coalesce((m ->> 'notice')::boolean, false));
      end if;
      if v_status = 'pending_approval' then
        update public.hub_licences set drafts = drafts + 1 where unit_id = t.unit_id and topic_key = any (v_topics);
      end if;
    end if;
  end loop;
  if v_seq > 0 and not v_test then update public.hub_conversations set last_assistant_at = now() where id = c.id; end if;
  -- «لم أعرف الإجابة» (not from a test run: nothing reaches a team)
  if not v_test and jsonb_typeof(p -> 'unanswered') = 'array' then
    perform internal.hub_unanswered_add(c, x::uuid, null, v_topics[1]) from jsonb_array_elements_text(p -> 'unanswered') x where x ~ '^[0-9a-f-]{36}$';
  end if;
  select unit_id into v_unit from public.hub_conversations where id = c.id;
  return jsonb_build_object('ok', true, 'cost_usd', v_cost, 'messages', v_out, 'send', v_send, 'test', v_test,
                            'alerts', exists (select 1 from public.hub_staff_sends s where s.status = 'queued' and not s.is_test),
                            'context', case when v_send then (select internal.hub_send_context(x) from public.hub_conversations x where x.id = c.id) end);
end;
$$;

-- internal.hub_report_data (20261115200000, copied): the voice and image faults (H7)

create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z)
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.published_at >= v_from and k.published_at < v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    'built_at', now());
end;
$$;

-- public.hub_retention (20261114200000, copied): a voice note's transcript is cleared with the message text (H7)

create or replace function public.hub_retention(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_months integer := internal.hub_setting_int('hub_retention_months', 12);
  v_days integer := internal.hub_setting_int('hub_media_retention_days', 90);
  v_texts integer;
  v_media integer;
  v_excerpts integer;
  v_turns integer;
  v_drafts integer;
  v_pending integer;
  v_req bigint;
  v_url text := internal.vault_value('job_sweep_url');
  v_token text := internal.vault_value('wa_cron_token');
begin
  perform set_config('app.actor', 'retention', true);
  update public.hub_messages
     set body = null, translation_ar = null, translation_en = null, transcript = null, purged_at = p_now
   where purged_at is null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_texts = row_count;
  update public.hub_messages set media_pending_delete = true
   where media_path is not null and not media_pending_delete and created_at < p_now - make_interval(days => v_days);
  get diagnostics v_media = row_count;
  update public.hub_unanswered set question_excerpt = null
   where question_excerpt is not null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_excerpts = row_count;
  -- H5: the understanding (guest text) and the drafts' fields follow the same 12 months
  update public.hub_turns set understanding = null, purged_at = p_now
   where purged_at is null and understanding is not null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_turns = row_count;
  update public.hub_drafts set fields = '{}'::jsonb, purged_at = p_now
   where purged_at is null and created_at < p_now - make_interval(months => v_months);
  get diagnostics v_drafts = row_count;
  select count(*) into v_pending from public.hub_messages where media_pending_delete;
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (null, 'retention', 'hub_retention', to_char(p_now at time zone 'Asia/Riyadh', 'YYYY-MM-DD'), null, 'update', null,
          jsonb_build_object('texts', v_texts, 'media', v_media, 'excerpts', v_excerpts, 'turns', v_turns, 'drafts', v_drafts, 'months', v_months, 'days', v_days), gen_random_uuid());
  if v_pending > 0 and coalesce(v_url, '') <> '' and coalesce(v_token, '') <> '' and v_url ~ '/functions/v1/' then
    v_req := net.http_post(
      url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/wa-automation'),
      body := jsonb_build_object('action', 'hub-media-purge'),
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-cron', v_token),
      timeout_milliseconds := 60000);
  end if;
  return jsonb_build_object('ok', true, 'texts', v_texts, 'media', v_media, 'excerpts', v_excerpts, 'turns', v_turns, 'drafts', v_drafts, 'pending', v_pending, 'request', v_req);
end;
$$;

-- public.hub_thread (20261114200000, copied): the transcript, its length, the image category, the media outcome (H7)

create or replace function public.hub_thread(p_conversation uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  ch public.hub_channels;
  st jsonb;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or not internal.can_unit(c.unit_id, 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  st := internal.hub_assistant_state(u);
  return jsonb_build_object(
    'conversation', jsonb_build_object(
      'id', c.id, 'unit_id', u.id, 'unit_key', u.key, 'unit_kind', u.kind, 'branch', u.branch_slug,
      'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar),
      'channel_kind', ch.kind, 'channel_address', ch.address, 'sending_enabled', ch.sending_enabled,
      'state', c.state, 'state_before_human', c.state_before_human, 'test_state', c.test_state, 'owner_kind', c.owner_kind, 'owner_staff_id', c.owner_staff_id,
      'owner_name', internal.staff_name(c.owner_staff_id), 'human_reason', c.human_reason, 'priority', c.priority,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'waiting_since', c.waiting_since,
      'last_guest_at', c.last_guest_at, 'last_staff_at', c.last_staff_at, 'tags', to_jsonb(c.tags), 'topics', to_jsonb(c.topics),
      'referral', c.referral, 'created_at', c.created_at, 'closed_at', c.closed_at, 'is_test', c.is_test,
      'can_edit', internal.can_unit(c.unit_id, 'edit'),
      'unit_mode', u.assistant_mode,
      'assistant', jsonb_build_object('active', (st ->> 'active')::boolean, 'mode', st ->> 'mode', 'reason', st ->> 'reason'),
      'can_release', internal.can_unit(c.unit_id, 'edit') and c.state = 'human' and (st ->> 'active')::boolean and st ->> 'mode' in ('shadow', 'licensed'),
      'can_pause', internal.can_unit(c.unit_id, 'edit') and u.assistant_mode <> 'off',
      'templates_approved', (select coalesce(jsonb_agg(t.language order by t.language), '[]') from public.hub_templates t
                              where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.status = 'APPROVED')),
    'guest', jsonb_build_object(
      'id', g.id, 'name', g.name, 'wa_name', g.wa_profile_name, 'label', internal.hub_guest_label(g), 'phone', g.phone, 'language', g.language,
      'member', g.club_joined_at is not null, 'consent', g.consent, 'opted_out', g.wa_opt_out_at is not null, 'blocked', g.hub_blocked_at is not null,
      'marketing_hold', g.marketing_hold_at is not null, 'tags', to_jsonb(g.tags), 'notes', g.notes,
      'stays', (select count(*) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'last_stay', (select max(r.check_out) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                             order by r.check_in desc), '[]')
                     from (select * from public.reservations r where r.profile_id = g.id and internal.can_branch(r.branch) order by r.check_in desc limit 10) r)),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', m.id, 'direction', m.direction, 'author', m.author, 'staff_id', m.staff_id, 'staff_name', internal.staff_name(m.staff_id),
                   'kind', m.kind, 'body', m.body, 'payload', m.payload, 'language', m.language, 'media_path', m.media_path, 'media_mime', m.media_mime,
                   -- H7: «تفريغ صوتي» and the image's category
                   'transcript', m.transcript, 'transcript_seconds', m.transcript_seconds, 'media_category', m.media_category, 'media_status', m.media_status,
                   'media_purged', m.media_purged_at is not null or m.media_pending_delete, 'status', m.status, 'error_code', m.error_code,
                   'sent_at', m.sent_at, 'purged', m.purged_at is not null, 'unanswered', exists (select 1 from public.hub_unanswered q where q.message_id = m.id),
                   'translation', m.translation_ar, 'approved_by_name', internal.staff_name(m.approved_by), 'approved_at', m.approved_at,
                   'edited_before_send', m.edited_before_send, 'turn_id', m.turn_id,
                   'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', coalesce(k.live ->> 'title_ar', k.title_ar)) order by k.key), '[]')
                                 from public.hub_knowledge_cards k where k.id = any (m.source_card_ids)))
                   order by m.sent_at, m.created_at), '[]') from public.hub_messages m where m.conversation_id = c.id),
    'templates', (select coalesce(jsonb_agg(t order by t ->> 'at'), '[]') from (
                    select jsonb_build_object('source', 'booking', 'template', w.template, 'meta_template', w.meta_template, 'status', w.status, 'ref', w.ref,
                                              'branch', w.branch, 'language', w.language, 'at', w.created_at) t
                      from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                     where r.profile_id = g.id and internal.can_branch(r.branch) and w.status not in ('skipped')
                    union all
                    select jsonb_build_object('source', 'eyab', 'template', e.template, 'status', e.status, 'branch', e.branch, 'language', e.language, 'at', e.created_at)
                      from public.eyab_messages e where e.profile_id = g.id and e.status not in ('skipped') and internal.can_branch(e.branch)) s),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'reason', e.reason, 'at', e.at,
                                                           'actor', internal.staff_name(e.actor_staff_id)) order by e.at, e.id), '[]')
                 from public.hub_conversation_events e where e.conversation_id = c.id),
    'episodes', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'unit_name', xu.name_ar, 'state', x.state, 'created_at', x.created_at, 'closed_at', x.closed_at)
                                           order by x.created_at desc), '[]')
                   from public.hub_conversations x join public.hub_units xu on xu.id = x.unit_id
                  where x.guest_profile_id = g.id and x.id <> c.id and internal.can_unit(x.unit_id, 'view')),
    'transfer_units', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', coalesce(v.name_ar, t.name_ar)) order by t.sort), '[]')
                         from public.hub_units t left join public.dining_venues v on v.id = t.dining_venue_id where t.status = 'active' and t.id <> u.id),
    'team', (select coalesce(jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name) order by s.full_name), '[]')
               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id
               join public.staff_permissions sp on sp.user_id = s.user_id and sp.section = 'inbox' and sp.level >= 'edit'
              where m.unit_id = u.id and s.active),
    'timers', internal.hub_timers());
end;
$$;

-- public.hub_assistant_overview (20261114400000, copied): the media switches (H7)

create or replace function public.hub_assistant_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_all boolean := internal.all_branches();
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_edit', internal.can('assistant', 'edit'),
    'system_admin', internal.is_system_admin(),
    'all_branches', v_all,
    'engine_ready', internal.hub_engine_ready(),
    'inbox_ready', internal.hub_inbox_ready(),
    'budget', internal.hub_budget_state(),
    'units', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', u.id, 'key', u.key, 'kind', u.kind, 'name_ar', u.name_ar, 'name_en', u.name_en, 'branch', u.branch_slug, 'status', u.status,
        'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'sort', u.sort, 'persona_published', u.persona_live is not null, 'persona', u.persona_live,
        'persona_draft', u.persona, 'persona_pending', u.persona is distinct from u.persona_live and u.persona <> '{}'::jsonb,
        'knowledge_hidden', u.knowledge_hidden, 'lab', internal.hub_unit_lab(u),
        -- H7: «الفويس» / «الصور» and today's transcribed seconds
        'voice_on', u.voice_on, 'images_on', u.images_on, 'voice_used_seconds', (internal.hub_voice_state(u.id) ->> 'used_seconds')::numeric,
        'venue', (select jsonb_build_object('id', d.id, 'slug', d.slug, 'name_ar', d.name_ar, 'name_en', d.name_en, 'status', d.status, 'menu', d.menu)
                    from public.dining_venues d where d.id = u.dining_venue_id),
        'channels', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'address', c.address, 'waba_id', c.waba_id,
                                                                   'display_name', c.display_name, 'connected', c.connected, 'verified_at', c.verified_at,
                                                                   'provider_status', c.provider_status, 'quality_rating', c.quality_rating,
                                                                   'messaging_limit', c.messaging_limit, 'sending_enabled', c.sending_enabled) order by c.created_at)
                                from public.hub_channels c where c.unit_id = u.id), '[]'::jsonb),
        'members', coalesce((select jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name, 'role', s.role, 'branch', s.branch, 'active', s.active)
                                               order by s.full_name)
                               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id where m.unit_id = u.id), '[]'::jsonb),
        'gates', internal.hub_unit_gates_mode(u, 'test'),
        'gates_shadow', internal.hub_unit_gates_mode(u, 'shadow')) order by u.sort, u.key)
        from public.hub_units u where internal.can_branch(u.branch_slug) and (not u.is_test or internal.is_admin())), '[]'::jsonb),
    'staff', coalesce((select jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name, 'role', s.role, 'branch', s.branch) order by s.full_name)
                         from public.staff s where s.active and (s.branch is null or internal.can_branch(s.branch))), '[]'::jsonb),
    'settings', (select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) from public.settings s where s.key = any(internal.hub_setting_keys())),
    'switch_gates', jsonb_build_object('hub_assistant_on', internal.hub_switch_gates('hub_assistant_on'), 'hub_inbox_on', internal.hub_switch_gates('hub_inbox_on')),
    'recipients', case when v_all then coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'email', r.email, 'active', r.active, 'filter_confirmed_at', r.filter_confirmed_at) order by r.created_at, r.email)
        from public.booking_notification_recipients r where r.scope = 'hub_summary'), '[]'::jsonb) else null end,
    'templates', coalesce((
      select jsonb_agg(jsonb_build_object('channel_id', t.channel_id, 'unit', u.key, 'name', t.name, 'language', t.language, 'category', t.category,
                                          'status', t.status, 'reason', t.reason, 'read_at', t.read_at) order by u.sort, t.name, t.language)
        from public.hub_templates t join public.hub_channels c on c.id = t.channel_id join public.hub_units u on u.id = c.unit_id
       where internal.can_branch(u.branch_slug) and not t.is_test), '[]'::jsonb),
    'alerts', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'kind', a.kind, 'unit', u.key, 'payload', a.payload, 'created_at', a.created_at) order by a.created_at desc)
        from public.hub_alerts a left join public.hub_units u on u.id = a.unit_id
       where a.acknowledged_at is null and not a.is_test
         and ((a.unit_id is null and v_all) or (u.id is not null and internal.can_branch(u.branch_slug)))), '[]'::jsonb));
end;
$$;

-- public.hub_sim_usage (20261114400000, copied): «المحاكي»'s image (H7)

create or replace function public.hub_sim_usage(p_unit uuid, p_layer text, p_model text, p_in bigint, p_out bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_cost numeric;
begin
  if p_layer not in ('understand', 'tag', 'compose', 'vision', 'summary') then raise exception 'hub_usage_layer' using errcode = '22023'; end if;
  v_cost := internal.hub_usage_add(p_unit, p_layer, 'simulator', p_model, p_in, p_out, false);
  return jsonb_build_object('ok', true, 'cost_usd', v_cost);
end;
$$;

-- public.hub_budget_overview (20261114200000, copied): the transcription has its own line (H7)

create or replace function public.hub_budget_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  b jsonb := internal.hub_budget_state();
  v_today date := (b ->> 'day')::date;
  v_month date := date_trunc('month', v_today)::date;
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'state', b, 'system_admin', internal.is_system_admin(),
    'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
    'models', (select s.value from public.settings s where s.key = 'hub_models'),
    'by_unit', coalesce((select jsonb_agg(jsonb_build_object('unit', u.key, 'name', u.name_ar, 'today', x.today, 'month', x.month) order by u.sort)
                           from (select d.unit_id, sum(d.cost_usd) filter (where d.day = v_today) as today, sum(d.cost_usd) as month
                                   from public.hub_usage_daily d where d.day >= v_month and d.day <= v_today and d.layer <> 'transcribe' group by d.unit_id) x
                           join public.hub_units u on u.id = x.unit_id where internal.can_branch(u.branch_slug)), '[]'::jsonb),
    -- H7: OpenAI's transcription — its own line (seconds and USD), outside the Claude budget; the daily cap per unit
    'audio', (select jsonb_build_object('today_seconds', coalesce(sum(d.audio_seconds) filter (where d.day = v_today), 0), 'month_seconds', coalesce(sum(d.audio_seconds), 0),
                                        'today_usd', coalesce(sum(d.cost_usd) filter (where d.day = v_today), 0), 'month_usd', coalesce(sum(d.cost_usd), 0),
                                        'cap_minutes', internal.hub_setting_int('hub_voice_daily_minutes', 60))
                from public.hub_usage_daily d join public.hub_units u on u.id = d.unit_id
               where d.layer = 'transcribe' and d.day >= v_month and d.day <= v_today and internal.can_branch(u.branch_slug)),
    'by_layer', coalesce((select jsonb_agg(jsonb_build_object('layer', x.layer, 'source', x.source, 'calls', x.calls, 'today', x.today, 'month', x.month, 'seconds', x.seconds) order by x.layer, x.source)
                            from (select d.layer, d.source, sum(d.calls) as calls, sum(d.cost_usd) filter (where d.day = v_today) as today, sum(d.cost_usd) as month, sum(d.audio_seconds) as seconds
                                    from public.hub_usage_daily d join public.hub_units u on u.id = d.unit_id
                                   where d.day >= v_month and d.day <= v_today and internal.can_branch(u.branch_slug) group by d.layer, d.source) x), '[]'::jsonb));
end;
$$;

-- ───────────────────────────────────────────── 3. settings ─────────────────────────────────────────────
insert into public.settings (key, value) values ('hub_voice_daily_minutes', '60') on conflict (key) do nothing;
update public.settings set value = value || '{"transcribe": "gpt-transcribe", "vision": "claude-haiku-5-5"}'::jsonb
 where key = 'hub_models' and jsonb_typeof(value) = 'object' and not (value ? 'transcribe');
update public.settings
   set value = value || '{"gpt-transcribe": {"per_minute": 0.0045, "provider": "openai", "source": "https://developers.openai.com/api/docs/pricing", "read_at": "2026-11-15"}}'::jsonb
 where key = 'hub_model_prices' and jsonb_typeof(value) = 'object' and not (value ? 'gpt-transcribe');

-- ───────────────────────────────────────────── 4. the switches ─────────────────────────────────────────────
-- switching «الفويس» or «الصور» ON is the system admin's (and the service role's — the preview-branch checks); OFF is any
-- assistant: edit holder of the branch. On every path: the RPC, a revert, a direct statement.
create function internal.hub_units_media_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if ((new.voice_on and not coalesce(old.voice_on, false)) or (new.images_on and not coalesce(old.images_on, false)))
     and not internal.is_system_admin() and not internal.hub_is_service() then
    raise exception 'hub_system_admin_only' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger hub_units_media_guard before update of voice_on, images_on on public.hub_units for each row execute function internal.hub_units_media_guard();

-- «الفويس» / «الصور» of one unit (assistant: edit in the unit's branch; audited, «تراجع» through revert_batch)
create function public.hub_unit_media_set(p_unit uuid, p_voice boolean, p_images boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_batch uuid;
begin
  select * into u from public.hub_units where id = p_unit for update;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('assistant', 'edit') or not internal.can_branch(u.branch_slug) then raise exception 'not allowed' using errcode = '42501'; end if;
  if u.status <> 'active' and (coalesce(p_voice, false) or coalesce(p_images, false)) then raise exception 'hub_unit_hidden' using errcode = 'P0001'; end if;
  if coalesce(p_voice, u.voice_on) = u.voice_on and coalesce(p_images, u.images_on) = u.images_on then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_units set voice_on = coalesce(p_voice, voice_on), images_on = coalesce(p_images, images_on) where id = p_unit;
  return jsonb_build_object('ok', true, 'batch_id', v_batch);
end;
$$;

-- ───────────────────────────────────────────── 5. the minutes ─────────────────────────────────────────────
-- the unit's transcribed seconds today (Riyadh) of live turns, and the cap (Settings hub_voice_daily_minutes)
create function internal.hub_voice_state(p_unit uuid, p_now timestamptz default now()) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'cap_seconds', internal.hub_setting_int('hub_voice_daily_minutes', 60) * 60,
    'used_seconds', coalesce((select sum(d.audio_seconds) from public.hub_usage_daily d
                               where d.unit_id = p_unit and d.layer = 'transcribe' and d.source = 'turn' and not d.is_test
                                 and d.day = (p_now at time zone 'Asia/Riyadh')::date), 0),
    'day', (p_now at time zone 'Asia/Riyadh')::date)
$$;

-- one transcription into hub_usage_daily: the seconds and their cost (hub_model_prices.<model>.per_minute) — never in the
-- Claude budget's alerts (internal.hub_budget_state leaves the layer out)
create function internal.hub_audio_add(p_unit uuid, p_source text, p_model text, p_seconds numeric, p_test boolean, p_now timestamptz default now())
returns numeric
language plpgsql security definer set search_path = '' as $$
declare
  v_secs numeric := greatest(coalesce(p_seconds, 0), 0);
  v_pm numeric := (select case when jsonb_typeof(s.value -> p_model -> 'per_minute') = 'number' then (s.value -> p_model ->> 'per_minute')::numeric end
                     from public.settings s where s.key = 'hub_model_prices');
  v_cost numeric := round(v_secs / 60.0 * coalesce(v_pm, 0), 6);
begin
  insert into public.hub_usage_daily (day, unit_id, layer, source, calls, input_tokens, output_tokens, cost_usd, audio_seconds, is_test)
  values ((p_now at time zone 'Asia/Riyadh')::date, p_unit, 'transcribe', p_source, 1, 0, 0, v_cost, v_secs, coalesce(p_test, false))
  on conflict (day, unit_id, layer, source, is_test) do update
     set calls = public.hub_usage_daily.calls + 1, cost_usd = public.hub_usage_daily.cost_usd + excluded.cost_usd,
         audio_seconds = public.hub_usage_daily.audio_seconds + excluded.audio_seconds;
  return v_cost;
end;
$$;

-- «المحاكي»'s transcription (hub-admin, service role)
create function public.hub_sim_audio(p_unit uuid, p_model text, p_seconds numeric, p_source text default 'simulator') returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if p_source not in ('simulator', 'test_lab') then raise exception 'hub_usage_source' using errcode = '22023'; end if;
  return jsonb_build_object('ok', true, 'cost_usd', internal.hub_audio_add(p_unit, p_source, p_model, p_seconds, false));
end;
$$;

-- today's voice minutes of each unit in the caller's scope («الميزانية»; assistant: view; numbers only)
create function public.hub_voice_usage() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('assistant', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'cap_minutes', internal.hub_setting_int('hub_voice_daily_minutes', 60),
    'units', coalesce((select jsonb_agg(jsonb_build_object('id', u.id, 'key', u.key, 'name_ar', u.name_ar, 'voice_on', u.voice_on, 'images_on', u.images_on,
                                                           'used_seconds', (internal.hub_voice_state(u.id) ->> 'used_seconds')::numeric) order by u.sort, u.key)
                         from public.hub_units u where internal.can_branch(u.branch_slug) and not u.is_test), '[]'::jsonb));
end;
$$;

-- ───────────────────────────────────────────── 6. the H7 conversations as test-lab items ─────────────────────────────────────────────
do $media$
declare v_sort integer;
begin
  perform set_config('app.actor', 'H7 — migration, Ahmed''s brief', true);
  v_sort := coalesce((select max(x.sort) + 1 from public.hub_test_items x), 0);
  insert into public.hub_test_items (key, unit_key, language, messages, expect, note, tags, added_from, sort)
  select e ->> 'id', e ->> 'unit', e ->> 'language', e -> 'messages', e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($media_bank$[{"id":"c101","unit":"airport-road","language":"ar","messages":["[voice] السلام عليكم، فيه مواقف للسيارات عندكم؟"],"expect":{"action":"conversation","steps":[{"outcome":"answer","media":"transcribed","salaam":true,"greeting":true,"must_include":["مجان"]}]},"note":"H7: a voice question answered in text","tags":["conversation","media","voice_answer","h7"]},{"id":"c102","unit":"shafa-road","language":"ar","messages":["[voice:fail]","[voice] متى وقت الفطور؟"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","media":"failed_transcribe","must_include":["سيكمل معك أحد أفراد فريقنا"],"summary_includes":"رسالة صوتية تعذّر تفريغها"},{"outcome":"answer","media":"transcribed"}]},"note":"H7: a voice note that cannot be transcribed → the hand-off notice; the next voice question is still answered while the team is waited for","tags":["conversation","media","voice_fail","h7"]},{"id":"c103","unit":"airport-road","language":"ar","messages":["[image:id_document] ‖ هذه هويتي للتسجيل"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","category":"id_document","must_include":["سيكمل معك أحد أفراد فريقنا"],"summary_includes":"صورة مستند"}]},"note":"H7: an identity image → the team, nothing read from it","tags":["conversation","media","id_image","h7"]},{"id":"c104","unit":"airport-road","language":"ar","messages":["[image:screenshot] صفحة الحجز في موقع أرمادا ريزيدنس — طريق المطار، سطر «سياسة الإلغاء» ‖ يعني أقدر ألغي مجانًا؟"],"expect":{"action":"conversation","steps":[{"outcome":["answer","handoff"],"category":"screenshot","must_include":["مجان"]}]},"note":"H7: a screenshot of the booking page's cancellation line, read with the caption and answered from the policy","tags":["conversation","media","screenshot","h7"]},{"id":"c105","unit":"shafa-road","language":"ar","messages":["[image:problem] تسرّب مياه من سقف الحمام ‖ الحمام يخر موية"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","category":"problem","priority":"high","summary_includes":"تسرّب مياه","must_include":["سيكمل معك أحد أفراد فريقنا"]}]},"note":"H7: a photo of a problem → an acknowledgement and the notice, high priority, the photo's line in the staff alert","tags":["conversation","media","problem_photo","h7"]},{"id":"c106","unit":"airport-road","language":"ar","messages":["[sticker]","عندكم واي فاي؟","[sticker]"],"expect":{"action":"conversation","steps":[{"outcome":"reply","greeting":true},{"outcome":"answer"},{"outcome":"none"}]},"note":"H7: a sticker is read like an emoji — a short reply as the first message, nothing later","tags":["conversation","media","sticker","h7"]},{"id":"c107","unit":"airport-road","language":"ar","messages":["[video]"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","must_include":["وصلتنا رسالتك"]}]},"note":"H7: a video stays with the team, as decided","tags":["conversation","media","video","h7"]},{"id":"c108","unit":"shafa-road","language":"en","messages":["[voice] Hi, do you have parking, and is it free?"],"expect":{"action":"conversation","steps":[{"outcome":"answer","media":"transcribed","greeting":true,"must_include":["free"]}]},"note":"H7: an English voice question answered in English","tags":["conversation","media","voice_answer","h7"]},{"id":"c109","unit":"airport-road","language":"ar","messages":["[voice:long]"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","media":"too_long","summary_includes":"أطول من خمس دقائق"}]},"note":"H7: a voice note longer than 5 minutes goes to the team untranscribed","tags":["conversation","media","voice_fail","h7"]}]$media_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end;
$media$;

-- ───────────────────────────────────────────── 7. grants ─────────────────────────────────────────────
revoke execute on function internal.hub_units_media_guard(), internal.hub_voice_state(uuid, timestamptz),
  internal.hub_audio_add(uuid, text, text, numeric, boolean, timestamptz) from public, anon, authenticated;
revoke execute on function public.hub_sim_audio(uuid, text, numeric, text) from public, anon, authenticated;
grant execute on function public.hub_sim_audio(uuid, text, numeric, text) to service_role;
revoke execute on function public.hub_unit_media_set(uuid, boolean, boolean), public.hub_voice_usage() from public, anon;
grant execute on function public.hub_unit_media_set(uuid, boolean, boolean), public.hub_voice_usage() to authenticated;
